static int 
dtb_termp_objlist_create(
    DtbTermpPropDialogInfo instance,
    Widget parent
)
{
    Arg	args[16];	/* need 11 args (add 5 to be safe) */
    int	n = 0;
    
    
    if (instance->objlist == NULL) {
        n = 0;
        XtSetArg(args[n], XmNscrollBarDisplayPolicy, XmAUTOMATIC);  ++n;
        XtSetArg(args[n], XmNlistSizePolicy, XmVARIABLE);  ++n;
        XtSetArg(args[n], XmNselectionPolicy, XmBROWSE_SELECT);  ++n;
        XtSetArg(args[n], XmNvisibleItemCount, 4);  ++n;
        XtSetArg(args[n], XmNbottomOffset, 4);  ++n;
        XtSetArg(args[n], XmNbottomAttachment, XmATTACH_FORM);  ++n;
        XtSetArg(args[n], XmNrightOffset, 4);  ++n;
        XtSetArg(args[n], XmNrightAttachment, XmATTACH_FORM);  ++n;
        XtSetArg(args[n], XmNleftOffset, 6);  ++n;
        XtSetArg(args[n], XmNleftAttachment, XmATTACH_WIDGET);  ++n;
        XtSetArg(args[n], XmNtopOffset, 4);  ++n;
        XtSetArg(args[n], XmNtopAttachment, XmATTACH_FORM);  ++n;
        XtSetArg(args[n], XmNx, 150);  ++n;
        XtSetArg(args[n], XmNy, 3);  ++n;
        instance->objlist =
            XmCreateScrolledList(parent,
                "objlist", args, n);
    }
    instance->objlist_scrolledwin = XtParent(instance->objlist);
    if (instance->objlist == NULL)
        return -1;

    return 0;
}



