static int 
dtb_termp_menu_field_create(
    DtbTermpPropDialogInfo instance,
    Widget parent
)
{
    Arg	args[18];	/* need 13 args (add 5 to be safe) */
    int	n = 0;
    
    if (instance->menu_field == NULL) {
        n = 0;
        XtSetArg(args[n], XmNbottomAttachment, XmATTACH_NONE);  ++n;
        XtSetArg(args[n], XmNrightOffset, 0);  ++n;
        XtSetArg(args[n], XmNrightAttachment, XmATTACH_FORM);  ++n;
        XtSetArg(args[n], XmNleftOffset, 4);  ++n;
        XtSetArg(args[n], XmNleftAttachment, XmATTACH_WIDGET);  ++n;
        XtSetArg(args[n], XmNtopOffset, 0);  ++n;
        XtSetArg(args[n], XmNtopAttachment, XmATTACH_FORM);  ++n;
        XtSetArg(args[n], XmNmaxLength, 80);  ++n;
        XtSetArg(args[n], XmNx, 232);  ++n;
        XtSetArg(args[n], XmNy, 2);  ++n;
        XtSetArg(args[n], XmNeditable, True);  ++n;
        XtSetArg(args[n], XmNcursorPositionVisible, True);  ++n;
        XtSetArg(args[n], XmNcolumns, 18);  ++n;
        instance->menu_field =
            XmCreateTextField(parent,
                "menu_field", args, n);
    }
    if (instance->menu_field == NULL)
        return -1;

    return 0;
}



